import json

with open('json/posts.json', 'r') as f:
    posts = json.load(f)

# Aggregate by OwnerUserId
user_stats = {}
for post in posts:
    owner_id = post.get('OwnerUserId')
    if owner_id is not None:
        if owner_id not in user_stats:
            user_stats[owner_id] = {'post_count': 0, 'total_score': 0}
        user_stats[owner_id]['post_count'] += 1
        user_stats[owner_id]['total_score'] += post.get('Score', 0)

# Filter to users with more than 10 posts
filtered_users = {uid: stats for uid, stats in user_stats.items() if stats['post_count'] > 10}

print(f"Total unique users: {len(user_stats)}")
print(f"Users with more than 10 posts: {len(filtered_users)}")
print("\nSample of filtered users:")
for i, (uid, stats) in enumerate(filtered_users.items()):
    if i < 5:
        print(f"User {uid}: post_count={stats['post_count']}, total_score={stats['total_score']}")
